create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text unique, display_name text, avatar_url text, created_at timestamptz default now());
create table public.articles (id bigint generated by default as identity primary key, title text not null, slug text unique not null, description text, content text, image_url text, category text not null, source_name text, source_url text, tags text[] default '{}', published_at timestamptz, created_at timestamptz default now());
create table public.saved_articles (id bigint generated by default as identity primary key, user_id uuid references auth.users(id) on delete cascade not null, article_id bigint references public.articles(id) on delete cascade not null, created_at timestamptz default now(), unique(user_id, article_id));
create table public.stories (id bigint generated by default as identity primary key, user_id uuid references auth.users(id) on delete cascade not null, content text not null check (char_length(content) between 1 and 5000), category text not null default 'ชีวิตประจำวัน', visibility text not null default 'public' check (visibility in ('public','private')), love_count integer not null default 0, thanks_count integer not null default 0, hug_count integer not null default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.saved_stories (id bigint generated by default as identity primary key, user_id uuid references auth.users(id) on delete cascade not null, story_id bigint references public.stories(id) on delete cascade not null, created_at timestamptz default now(), unique(user_id, story_id));
alter table public.profiles enable row level security; alter table public.articles enable row level security; alter table public.saved_articles enable row level security; alter table public.stories enable row level security; alter table public.saved_stories enable row level security;
create policy "Public articles are readable" on public.articles for select using (true);
create policy "Own profile readable" on public.profiles for select using (auth.uid() = id); create policy "Own profile editable" on public.profiles for update using (auth.uid() = id);
create policy "Own saved readable" on public.saved_articles for select using (auth.uid() = user_id);
create policy "Public stories readable" on public.stories for select using (visibility = 'public' or auth.uid() = user_id); create policy "Own saved stories readable" on public.saved_stories for select using (auth.uid() = user_id); create policy "Own saved stories insertable" on public.saved_stories for insert with check (auth.uid() = user_id); create policy "Own saved stories deletable" on public.saved_stories for delete using (auth.uid() = user_id); create policy "Own stories insertable" on public.stories for insert with check (auth.uid() = user_id); create policy "Own stories editable" on public.stories for update using (auth.uid() = user_id); create policy "Own stories deletable" on public.stories for delete using (auth.uid() = user_id); create policy "Own saved insertable" on public.saved_articles for insert with check (auth.uid() = user_id); create policy "Own saved deletable" on public.saved_articles for delete using (auth.uid() = user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, username, display_name) values (new.id, split_part(new.email, '@', 1), coalesce(new.raw_user_meta_data->>'full_name', split_part(new.email, '@', 1))); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
